/* LISA-06 €5 note delta, Opus 5.5 18.11.26: two-cell span 27.6 x 13.6rem (227.9 x 112.3 px at 1128x752). Aspect 120:62 kept; the note is not drawn to coin scale. */
.screen.mg-shop .mgs-money.mgs-notecell { width: 27.6rem; }
.screen.mg-shop .mgs-note { position: absolute; left: 50%; top: 6.2rem; width: 23.2rem; height: auto; aspect-ratio: 300 / 155; translate: -50% -50%; display: block; pointer-events: none; user-select: none; -webkit-user-drag: none; filter: drop-shadow(0 .4rem 0 rgba(0,0,0,.2)); }
.screen.mg-shop .mgs-bitem .mgs-note { position: relative; left: auto; top: auto; translate: none; width: 12rem; }
